    "distractor_exp": "- ① 변화 시점은 동시에 일어나지 않고 각 개입 도입에 맞추어 시차를 보인다.\n  - ③ 기초선 길이의 시차는 다중기초선설계의 핵심 통제전략이다.\n  - ④ 시각분석은 평균뿐 아니라 수준·추세·변산성·즉시성·중첩·반복성을 본다.\n  - ⑤ 다중기초선은 개입을 철회하지 않고도 시차와 반복으로 실험적 통제를 검토한다.",
