    "difficulty": "최상 | 출제위원 A (이론·원전·법령)",
    "cognitive": "분석",
    "domain": "/난이도:",
    "stem": "다음은 상담센터에 의뢰된 고등학교 2학년 A군(17세)의 사례 기록이다.\n\n> A군은 성적 우수 장학금을 받아 명문대에 진학하여 가난에서 벗어나겠다는 강한 열망을 품고 성실히 학업에 매진해 왔다. 그러나 최근 중간고사에서 부정행위 누명을 쓰고 전 과목 0점 처리 및 유급 위기에 처했다. 억울함을 호소했으나 교사와 부모 모두 믿어주지 않자 극심한 분노와 좌절감을 느낀 A군은 학교 기물을 파손하고, SNS에 교사를 협박하는 글을 게시하였다.\n\nA군의 비행 발생 경로를 **Agnew의 일반긴장이론(General Strain Theory)**과 **Merton의 고전적 아노미(Anomie/Strain) 이론**의 관점에서 비교 분석한 설명으로 가장 적절한 것은?",
