    "explanation": "Agnew의 일반긴장이론은 전통적 긴장이론을 확장하여 세 가지 긴장원천인 (1) 목표 달성의 실패, (2) 긍정적 자극의 상실, (3) 혐오적/부정적 자극의 제시를 제시하고, 이러한 긴장이 '분노(Anger)' 등 부정적 정서를 유발하며, 정서적·인지적·행동적 대처 자원이 부족할 때 비행으로 이어진다고 설명한다. A군의 사례는 억울한 누명과 부당한 처벌이라는 혐오적 자극의 제시 및 분노 정서의 폭발로 인한 외재화 비행을 가장 정확히 설명한다.",
    "distractor_exp": "- **①** Merton의 혁신형은 문화적 목표(부, 성공)를 수용하되 불법적 수단(절도, 사기 등)을 사용하는 것이며, A군의 보복적 기물 파손 및 협박은 혁신형이 아니라 반발형/반항형에 가까우며 Merton 이론만으로는 정서적 분노 표출을 온전히 설명하기 어렵다.\n- **②** Agnew 이론에서 A군의 상태는 '목표 달성 실패'뿐만 아니라 '교사/부모의 불신 및 징계'라는 '혐오적 자극의 발생'과 '성적·인정 상실'이 복합 작용한 것이다.\n- **③** 불법적 기회구조와의 접촉을 통한 비행 학습은 Cloward와 Ohlin의 차별기회이론의 설명이다.\n- **⑤** 주관적 긴장과 '부정적 정서(특히 분노)'의 매개 역할을 핵심으로 명시한 것은 Agnew의 일반긴장이론이며, Merton의 고전 이론은 거시적 사회구조적 불일치에 초점을 둔다.",
    "citation": "Agnew, R. (1992). *Foundation for a General Strain Theory of Crime and Delinquency*. **Criminology, 30**(1), 47–88. [DOI: 10.1111/j.1745-9125.1992.tb01093.x]",
