    "distractor_exp": "- **①** 개인의 고정된 내적 특성(낮은 자기통제력)을 강조하는 것은 자기통제이론이며, 사회적 유대의 강도와 변화를 강조하는 것이 사회통제이론이다.\n- **②** 인습적 규범과 가치관을 타당하다고 믿는 것은 '신념(Belief)'에 해당한다.\n- **④** 투자한 시간과 에너지의 손실을 우려하는 합리적 계산 요소는 '전념(Commitment)'이며, '참여(Involvement)'는 인습적 활동에 바쁘게 참여하여 비행할 여가 시간을 없애는 것이다.\n- **⑤** 자기통제이론은 대략 8~10세경 확립된 자기통제력이 생애 전반에 걸쳐 비교적 안정적으로 유지된다고 보며, 성인기 유대에 의한 전환점을 강조한 것은 Sampson & Laub의 연령등급 생애과정이론이다.",
