    "domain": "/난이도:",
    "stem": "Moffitt의 이원적 발달경로 이론(Developmental Taxonomy)에 근거하여 다음 두 청소년(갑, 을)의 특성을 평가하고 상담 개입을 계획하고자 한다.\n\n| 구분 | 청소년 갑 (16세) | 청소년 을 (16세) |\n|---|---|---|\n| **발병 시기** | 7세경부터 주의집중 곤란, 충동성, 또래 공격성, 거짓말 시작 | 14세 중학교 입학 후 흡연, 무단결석, 또래 무리와의 절도 시작 |\n| **신경심리적 요인** | 유아기 까다로운 기질, 언어발달 지연 및 실행기능 결함 관찰됨 | 신경심리적 결함 없음, 초등학교 시절 학업 및 교우관계 원만함 |\n| **비행 양상** | 단독 비행 및 집단 비행 모두 빈번, 상황(가정, 학교, 거리)에 무관하게 지속 | 주로 또래 집단과 함께할 때 발생, 성인 역할을 모방하는 지위비행 위주 |\n| **가족 환경** | 부모의 거부적·일관성 없는 훈육 및 가정 내 갈등 심각 | 부모의 일반적 양육 태도 양호하나 최근 또래 관계 통제에 어려움 호소 |\n\n갑과 을에 대한 사정 및 개입 전략으로 가장 적절한 것은?",
