    "stem": "보호관찰소에 연계된 청소년 내담자 B군(16세, 폭력 및 특수절도 전력)에 대해 Andrews와 Bonta의 RNR 모형을 적용하여 개입 계획을 수립하고자 한다. B군에 대한 평가 결과는 다음과 같다.\n\n> - **위험도 평가:** YLS/CMI 총점 '고위험(High Risk)' 수준\n> - **주요 욕구:** 비행 또래집단과의 강한 유대, 충동적 성향 및 친범죄적 태도(규범 위반 정당화) 보유. 한편, 경미한 우울감 및 과거 학업 부진으로 인한 자존감 저하 호소.\n> - **학습 스타일:** 언어적 통찰 능력이 다소 부족하나, 구체적 역할극(Role-play)과 행동 시연에 대한 집중도와 반응성이 우수함.\n\nRNR 원칙에 입각한 상담 개입 전략으로 가장 적절한 것은?",
