    "explanation": "RNR 모형의 핵심 원칙:\n1. **위험 원칙(Risk):** 재범 위험 수준에 맞춰 개입 강도를 조절함(고위험군에게 고강도 개입 제공).\n2. **욕구 원칙(Need):** 재범과 직접 관련된 '범죄유발적 욕구(Criminogenic Needs: 친범죄적 태도, 비행 또래, 충동성 등)'를 표적으로 삼음 (자존감, 단순 우울 등은 비범죄유발적 요인임).\n3. **반응성 원칙(Responsivity):** 내담자의 학습 스타일, 인지능력, 동기 수준에 맞춰 개입 방식(인지행동치료, 역할연습 등)을 개별화함.\n따라서 B군의 행동적 학습 스타일에 맞추어 구조화된 인지행동적 개입과 역할연습을 적용하는 ③이 가장 적절하다.",
    "distractor_exp": "- **①** 고위험군에게는 최소 개입이 아니라 집중적이고 구조화된 고강도 개입이 필요하다.\n- **②** 자존감이나 단순 우울감은 '비범죄유발적 욕구(Non-criminogenic Need)'에 해당하므로 1차적 재범방지 표적으로 우선순위가 높지 않다.\n- **④** 친범죄적 태도와 비행 또래 관계는 수정 가능한 대표적인 '동적 위험요인(Dynamic Risk Factor)'이다.\n- **⑤** 비밀보장 예외 상황이 아닌 일상적 상담 내용을 동의 없이 무단 통보하는 것은 상담 윤리 위반이다.",
