    "domain": "/난이도:",
    "stem": "청소년 폭력 위험성 사정도구인 SAVRY(Structured Assessment of Violence Risk in Youth)를 활용하여 비행청소년의 폭력을 예측하고 관리하고자 한다. SAVRY의 구조와 운영 원리에 관한 설명으로 옳은 것을 모두 고른 것은?\n\n> ㄱ. SAVRY는 비구조화된 임상적 판단(Unstructured Clinical Judgment)의 한계를 극복하기 위해 통계적 계량 공식만으로 위험 등급을 기계적으로 산출하는 순수 보험통계적(Actuarial) 도구이다.  \n> ㄴ. SAVRY의 24개 위험요인은 '역사적 위험요인(Historical Risk Factors)', '사회·맥락적 위험요인(Social/Contextual Risk Factors)', '개인적 위험요인(Individual Risk Factors)'의 세 영역으로 구성된다.  \n> ㄷ. SAVRY는 위험요인뿐만 아니라 강력한 완충작용을 하는 6가지 '보호요인(Protective Factors: 친사회적 참여, 강한 사회적 유대 등)'을 함께 평가하여 전반적 위험 수준을 보정한다.  \n> ㄹ. 역사적 위험요인(예: 조기 폭력 폭로, 아동기 학대 경험)은 수정 가능한 동적 요인이므로 단기적 치료 목표로 우선 설정해야 한다.  \n> ㅁ. 평가자는 각 항목의 단순 점수 합산에 의존하지 않고, 위험요인과 보호요인의 상호작용을 통합한 '구조화된 전문적 판단(Structured Professional Judgment: SPJ)'에 따라 최종 위험 수준(저/중/고)을 결정한다.",
