    "explanation": "SAVRY는 대표적인 **구조화된 전문적 판단(SPJ)** 모델이다.\n- **ㄴ:** 24개 위험요인은 역사적(8항목), 사회맥락적(6항목), 개인적(10항목) 영역으로 구분됨.\n- **ㄷ:** 친사회적 참여, 학교 유대, 긍정적 태도 등 6가지 보호요인을 포함하여 평가함.\n- **ㅁ:** SPJ 도구는 점수의 기계적 합산이 아니라 임상가의 통합적 전문 판단을 통해 최종 위험도를 판정함.\n따라서 ㄴ, ㄷ, ㅁ이 옳다.",
    "distractor_exp": "- **ㄱ:** SAVRY는 기계적 점수 산출을 지양하는 '구조화된 전문적 판단(SPJ)' 도구이다.\n- **ㄹ:** 역사적 위험요인은 이미 과거에 발생하여 변경할 수 없는 '정적 위험요인(Static Factor)'이므로 치료 개입을 통해 직접 수정할 수 없다. 수정 가능한 것은 사회맥락적·개인적 영역의 '동적 위험요인'이다.",
